            values <- sequence [X.List <$> mapM (\item194 -> pure (X.Scalar w item194)) field189,X.List <$> mapM (\item195 -> X.List <$> mapM (\item196 -> pure (X.Scalar w item196)) item195) field190,X.List <$> mapM (\item197 -> X.List <$> mapM (\item198 -> pure (X.Scalar w item198)) item197) field191,X.List <$> mapM (\item199 -> (\(part200,part201) -> X.Tuple <$> sequence [pure (X.Scalar w part200),pure (X.Scalar w part201)]) item199) field192,X.List <$> mapM (\item202 -> pure (X.Index item202)) field193]
            pure(X.Tuple[X.Text "SparseSVD",X.Tuple values])

encodeProvider :: (B.Provider) -> IO X.Value
encodeProvider value=pure(opaque "HMath.Backend.Provider" (-1) value force view)
  where
    force=evaluate value >> pure ()
    view=case value of
        B.Pure  -> do
            values <- sequence []
            pure(X.Tuple[X.Text "Pure",X.Tuple values])
        B.OpenBLAS  -> do
            values <- sequence []
            pure(X.Tuple[X.Text "OpenBLAS",X.Tuple values])
        B.BLIS  -> do
            values <- sequence []
            pure(X.Tuple[X.Text "BLIS",X.Tuple values])
        B.OneMKL  -> do
            values <- sequence []
            pure(X.Tuple[X.Text "OneMKL",X.Tuple values])
        B.Accelerate  -> do
            values <- sequence []
            pure(X.Tuple[X.Text "Accelerate",X.Tuple values])

